import{_ as a,o as e,a as r,d as i}from"./chunks/framework.MWxrmMMs.js";const u=JSON.parse('{"title":"Сборки","description":"Сборки в Stuzhik: страница сборки, смена версии игры с откатом, бэкапы без повторов, настройки игры и пресеты графики, общие шейдеры, миры и скриншоты, перевод сборки и ярлык в Steam.","frontmatter":{"description":"Сборки в Stuzhik: страница сборки, смена версии игры с откатом, бэкапы без повторов, настройки игры и пресеты графики, общие шейдеры, миры и скриншоты, перевод сборки и ярлык в Steam.","head":[["meta",{"name":"keywords","content":"stuzhik сборка, смена версии minecraft, откат сборки, бэкап minecraft, пресеты графики minecraft, общие шейдеры, перевод модпака, minecraft steam deck"}]]},"headers":[],"relativePath":"guide/instances.md","filePath":"guide/instances.md"}'),o={name:"guide/instances.md"};function d(n,t,l,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="сборки" tabindex="-1">Сборки <a class="header-anchor" href="#сборки" aria-label="Permalink to &quot;Сборки&quot;">​</a></h1><p>Сборка: отдельный Minecraft со своими модами, конфигами и мирами. Сборки не влияют друг на друга: одна для выживания, другая для технических модов, третья для сервера с друзьями.</p><h2 id="создание" tabindex="-1">Создание <a class="header-anchor" href="#создание" aria-label="Permalink to &quot;Создание&quot;">​</a></h2><p>«Создать» в боковой панели (плюс, когда она свёрнута): клиент или сервер, версия игры и загрузчик (Fabric, Quilt, Forge, NeoForge или без загрузчика). Готовую сборку можно поставить из каталога модпаков, подробнее: <a href="/guide/modpacks.html">Модпаки</a>.</p><h2 id="страница-сборки" tabindex="-1">Страница сборки <a class="header-anchor" href="#страница-сборки" aria-label="Permalink to &quot;Страница сборки&quot;">​</a></h2><p>Слева название, «Играть» и вкладки, справа содержимое вкладки. Числа на вкладках всегда совпадают с тем, что внутри, и меняются сразу, где бы ни поменяли сборку: в лаунчере, файлом в папке или консольной версией.</p><table tabindex="0"><thead><tr><th>Вкладка</th><th>Что там</th></tr></thead><tbody><tr><td>Моды</td><td>моды сборки: включить, обновить, удалить (<a href="/guide/mods.html">Моды</a>)</td></tr><tr><td>Зависимости</td><td>что чего требует, конфликты, моды не для этой сборки</td></tr><tr><td>Модпак</td><td>обновление модпака, из которого сборка поставлена</td></tr><tr><td>Ресурсы, Шейдеры, Датапаки</td><td>паки сборки и общие паки</td></tr><tr><td>Скриншоты</td><td>снимки из игры</td></tr><tr><td>Анализ логов</td><td>разбор краша и шаги, что сделать (<a href="/guide/log-analyzer.html">Анализатор логов</a>)</td></tr><tr><td>Бэкапы</td><td>резервные копии сборки</td></tr><tr><td>Миры</td><td>миры сборки и их копирование</td></tr></tbody></table><p>Реже нужное лежит под «Ещё»: «Файлы» (редактор конфигов), «Профили», «Патчи», «Производительность» и «Консоль». У сервера вкладки свои: <a href="/guide/servers.html">Серверы</a>.</p><p>Действия со сборкой собраны в её меню (правая кнопка на карточке или «⋯»): «Игровые настройки», «Открыть папку», «Редактировать», «Экспорт сборки», «Сменить обложку», «Добавить в Steam», «Перевод сборки», «Починить» и другие.</p><h2 id="version-change" tabindex="-1">Смена версии игры или загрузчика <a class="header-anchor" href="#version-change" aria-label="Permalink to &quot;Смена версии игры или загрузчика {#version-change}&quot;">​</a></h2><p>В «Редактировать» поменяйте версию игры или загрузчик и сохраните. Откроется окно «Смена версии», где видно заранее:</p><ul><li><strong>Обновятся</strong>: моды, у которых есть версия под новую игру. Новые зависимости, которые им понадобятся, поставятся в том же переходе</li><li><strong>Выключатся</strong>: моды без такой версии. Они останутся в списке выключенными, их можно включить или заменить потом</li><li><strong>Останутся как есть</strong>: подходящие и закреплённые моды</li><li>что будет с мирами: в новой версии они обновятся при первом входе, в более старой могут пропасть блоки и предметы</li></ul><p>Перед сменой сохраняется точка отката: вся сборка вместе с мирами. Пока вы не нажали «Оставить», на странице сборки есть «Откатить»: он вернёт моды, конфиги, миры и версию как были.</p><p>Когда для игры сборки выходит новая стабильная версия загрузчика, на странице появляется подсказка «Вышла новая версия NeoForge: …». «Перейти…» открывает то же окно смены версии, «Не сейчас» прячет подсказку до следующей версии.</p><h2 id="бэкапы" tabindex="-1">Бэкапы <a class="header-anchor" href="#бэкапы" aria-label="Permalink to &quot;Бэкапы&quot;">​</a></h2><p>Бэкап делается сам перед обновлением и удалением модов (не чаще раза в 10 минут) и кнопкой «Создать бэкап» во вкладке «Бэкапы». Число автоматических бэкапов ограничено, ручные не удаляются.</p><p>Одинаковые файлы хранятся один раз на все бэкапы сборки: бэкап неизменённой сборки делается мгновенно и почти не занимает места, а после обновления мода добавляет только этот мод. Восстановить можно «Без миров» или «Вместе с мирами», и перезаписываются только изменившиеся файлы.</p><p>Если в сборке есть мод бэкапов (FTB Backups, Simple Backups и подобные), лаунчер это увидит и будет бэкапить только моды и конфиги: миры бэкапит мод.</p><h2 id="настроики-игры" tabindex="-1">Настройки игры <a class="header-anchor" href="#настроики-игры" aria-label="Permalink to &quot;Настройки игры&quot;">​</a></h2><p><strong>«Игровые настройки» сборки</strong>: её настройки Minecraft без запуска игры, а внутри <strong>пресеты графики</strong>: графику сборки можно сохранить под именем и применить к любой другой. В пресет входят видеонастройки игры, выбранный шейдер с его настройками и графика модов (Sodium, Iris, Embeddium, Distant Horizons и других). Поле зрения, яркость, масштаб интерфейса, управление и звук пресет не трогает. Пресет сохраняется в файл и загружается из файла.</p><p><strong>Настройки → В игре → Для всех сборок</strong>: дальность прорисовки, поле зрения, яркость, громкость, чувствительность мыши и остальное. Категория с переключателем «Во всех сборках» одинакова везде, и изменённое в игре возвращается в лаунчер; остальные значения получают новые сборки.</p><p><strong>Настройки → В игре → Язык и подсказки</strong>: обучающие подсказки Minecraft («Используйте WASD») и экранный диктор выключены по умолчанию, а новая сборка запускается на языке системы. Всё это возвращается переключателями там же.</p><p><strong>Настройки → Запуск → Свои настройки сборок</strong>: у каких сборок своя память, Java, аргументы или настройки игры вместо общих. Вернуть к общим можно одной кнопкой, для одной сборки или для всех.</p><h2 id="шеидеры-и-ресурспаки" tabindex="-1">Шейдеры и ресурспаки <a class="header-anchor" href="#шеидеры-и-ресурспаки" aria-label="Permalink to &quot;Шейдеры и ресурспаки&quot;">​</a></h2><ul><li><strong>Общий пак.</strong> Кнопка «Сделать общим: для всех сборок» в строке шейдера или ресурспака переносит файл в общую папку, и он подключается к каждой сборке при запуске игры. Настройки общего шейдера тоже общие, но свои настройки шейдера у сборки главнее</li><li><strong>Пресет шейдера.</strong> Кнопка «Пресет» у шейдерпака показывает профили, которые задал автор пака (например, Low, Medium, High у BSL и Complementary). Лаунчер меняет только файл настроек пака, остальные ваши настройки остаются</li></ul><h2 id="скриншоты-и-миры" tabindex="-1">Скриншоты и миры <a class="header-anchor" href="#скриншоты-и-миры" aria-label="Permalink to &quot;Скриншоты и миры&quot;">​</a></h2><p>Новый скриншот из игры и новый мир появляются во вкладках сами, без кнопки «Обновить». Скриншот можно сделать фоном лаунчера или обложкой сборки.</p><p>Мир копируется в другую сборку кнопкой «Копировать в…». Если там уже есть мир с тем же именем, копия получает новое («Мир (2)»), чужой мир она не трогает.</p><h2 id="build-translation" tabindex="-1">Перевод сборки <a class="header-anchor" href="#build-translation" aria-label="Permalink to &quot;Перевод сборки {#build-translation}&quot;">​</a></h2><p>«Перевод сборки» в меню сборки («Ещё…») собирает тексты, которые сборка несёт сама: квесты FTB Quests и Heracles, книги Patchouli, тексты KubeJS и OpenLoader, и показывает, сколько из них уже на русском.</p><ul><li>«Выгрузить строки…»: файл для переводчика, «Загрузить перевод…»: наложить готовый на сборку</li><li>«Взять из других версий»: добрать русский модов из других версий тех же модов на Modrinth и CurseForge: берутся только строки с тем же английским текстом</li><li>«Убрать перевод» возвращает файлы сборки в точности как были</li></ul><p>Перевод переживает обновление модпака и смену версии игры. Если у команды Stuzhik есть готовый перевод модпака, он ставится сам после установки и обновления сборки; выбрать «Спрашивать» или выключить можно в «Настройки → Моды».</p><h2 id="сборка-в-steam" tabindex="-1">Сборка в Steam <a class="header-anchor" href="#сборка-в-steam" aria-label="Permalink to &quot;Сборка в Steam&quot;">​</a></h2><p>«Добавить в Steam» в меню сборки добавляет её в библиотеку Steam как стороннюю игру. Она запускается из Big Picture и на Steam Deck сразу, без окна лаунчера, а Steam видит, сколько она шла. У неё своя обложка, плитка и логотип, сделанные из обложки сборки. Открытый Steam перезаписывает свои ярлыки при выходе, поэтому лаунчер закрывает и открывает его снова, только если вы нажали кнопку, которая это говорит.</p><h2 id="data-location" tabindex="-1">Где лежат данные <a class="header-anchor" href="#data-location" aria-label="Permalink to &quot;Где лежат данные {#data-location}&quot;">​</a></h2><p>Сборки, миры, Java, база и журналы лаунчера лежат в одной папке. <strong>Настройки → Хранилище → Расположение</strong> показывает, где она, и переносит её на любой диск: на тот же диск мгновенно (папка переименовывается при перезапуске), на другой копированием со сверкой каждого файла, после чего старая папка удаляется.</p><p>Портативный режим: положите файл <code>portable.txt</code> рядом с программой, и все данные, включая настройки интерфейса, будут в папке <code>data</code> рядом с ней.</p>',37)])])}const m=a(o,[["render",d]]);export{u as __pageData,m as default};
